// === Tab: mySketch ===
const sketch = (p) => {
    let H = 1024;
    let W = 1024;

    let min_width;
    let max_width;

    let G;

    let SEED;

    let flocks = [];

    let POSX = [];
    let POSY = [];
    let C1;

    let FRAME1 = 0;

    let BACK_COL;

    let T_RED = [];
    let T_GREEN = [];
    let T_BLUE = [];

    let FLAG;

    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);

        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED);

        base_color = p.random(256);

        G.rectMode(p.CENTER);
        G.noStroke();

        BACK_COL = 10;

        FLAG = p.random(1);

        C1 = 3;
        POSX.length = C1;
        POSY.length = C1;
        for(let i=0;i<C1;++i){
            while (true) {
                POSX[i] = W/2 + p.random(-W/4, W/4);
                POSY[i] = H/3 + p.random(-H/4, H/4);
                let flag = true;
                for(let j=0;j<i;++j){
                    if(p.dist(POSX[j], POSY[j], POSX[i], POSY[i]) < H/3){
                        flag = false;
                        break;
                    }
                }
                console.log(i, flag)
                if(flag) break;
            }
        }

        T_RED = [];
        T_GREEN = [];
        T_BLUE = [];

        for (let i=0;i<C1;++i){
            T_RED.push(p.random(100));
            T_GREEN.push(p.random(100));
            T_BLUE.push(p.random(100));
        }

        FRAME1 = 2000;
        let cycle1 = [2000];
        let csel1 = p.int(p.random(1));
        ini_coh = 2;
        mx_coh = 1.4;
        for(let k=0;k<C1;++k){
            flocks.push(new Flock());
            for(let i = 0; i < 100; ++i) {
                let speed = 4;
                let max_r = p.random(0);
                flocks[k].add(new Particle(0, speed, max_r, FRAME1, cycle1[csel1],  
                                            ini_coh, mx_coh, 1, k));
            }
        }



    };

    p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);
        p.loop();
    }

    p.draw = () => {
        p.blendMode(p.BLEND);
        p.background(BACK_COL);

        for(let k=0;k<C1;++k){
            flocks[k].run();
        }

        p.image(G, (p.width-min_width)/2, (p.height-min_width)/2, min_width, min_width, 0, 0, W, H);
    };

    class Flock {
        particles;

        constructor() {
            this.particles = [];
        }

        add(particle) {
            this.particles.push(particle);
        }

        run() {
            this.update();
            this.display();
        }

        update() {
            for (let i = 0; i < this.particles.length; ++i) {
                this.particles[i].update(this.particles);
            }
        }

        display() {
            for (let i = 0; i < this.particles.length; ++i) {
                this.particles[i].display();
            }
        }
    }

    class Particle {
        acceleration;
        velocity;
        position;
        center;
        radius;
        hole_r;
        max_r;
        color;
        col_sep;
        maxforce = 1.0;
        maxspeed;
        minspeed = 0.001;
        mode;
        ali_f = 0.0;
        coh_f = 0.0;
        max_coh;
        alpha;
        fcnt;
        cycle;
        lcnt;
        fin;

        constructor(mode, speed, max_r, lcnt, cycle, coh, mxcoh, alpha, sel) {
            this.acceleration = p.createVector(0, 0);

            this.mode = mode;
            this.radius = 1;
            this.max_r = max_r;
            this.alpha = alpha;

            this.ali_f = coh;
            this.coh_f = coh;
            this.max_coh = mxcoh;

            this.fcnt = 0;
            this.cycle = cycle;
            this.fin = false
            this.lcnt = lcnt;
            this.hole_r = p.random(H/15, H/10);
            if(this.mode == 0) {
                let r = p.random(0, this.hole_r);
                let deg = p.random(p.TAU);
                this.position = p.createVector(POSX[sel] + r * p.cos(deg), POSY[sel] - r * p.sin(deg));
                this.center = p.createVector(POSX[sel], POSY[sel]);
                this.maxspeed = speed;
                this.col_sep = 1.5;
                this.velocity = p.createVector(p.random(1), p.random(1));

                this.color = p.createVector(
                    p.min(255, p.max(0, T_RED[sel] + p.randomGaussian(0, 55))),//p.random(-30,30))),
                    p.min(255, p.max(0, T_GREEN[sel] + p.randomGaussian(0, 55))),// + p.random(-30,30))),
                    p.min(255, p.max(0, T_BLUE[sel] + p.randomGaussian(0, 55))),// + p.random(-30,30))),
                );
            }
            else {

            }

        }

        applyForce(force) {
            this.acceleration.add(force);
        }

        inner_update(particles) {
            let sep = this.separate(particles);
            let ali = this.align(particles);
            let coh = this.cohesion(particles);

            sep.mult(1.5);
            ali.mult(this.ali_f);
            coh.mult(this.coh_f);

            this.applyForce(sep);
            this.applyForce(ali);
            this.applyForce(coh);
        }

        update(particles) {
            if(this.fcnt >= this.lcnt) {this.fin = true;}
            if(this.fin){
                return;
            }
            this.inner_update(particles);
            this.velocity.add(this.acceleration);

            if (this.mode == 0) {
                this.velocity.add(p.createVector(
                    0.0, 0.0
                ));

                this.radius = (1-this.fcnt/this.cycle) * this.max_r + 5;
                this.ali_f = p.max(this.max_coh, this.ali_f-0.002);
                this.coh_f = p.max(this.max_coh, this.coh_f-0.002);
            }
            else {

            }

            if(p.random()<.5){
                this.velocity = p.createVector(p.random(-4,4), p.random(-4,4));
            }

            this.velocity.limit(this.maxspeed);
            this.position.add(this.velocity);
            this.border();
            this.acceleration.mult(0);


            if(this.fcnt < this.lcnt){
                this.fcnt += 1;
            }

        }

        border() {
            if(this.position.x > W) {this.position.x -= W;}
            else if(this.position.x < 0) {this.position.x += W;}
            if(this.position.y > H) {this.position.y -= H;}
            else if(this.position.y < 0) {this.position.y += H;}
        }

        seek(target){
            let v = p5.Vector.sub(target, this.position);
            v.normalize();
            v.mult(this.maxspeed);
            v.sub(this.velocity);
            v.limit(this.maxforce);
            return v;
        }

        separate(particles) {
            let inter_range = 250.0;
            var v = p.createVector(0, 0, 0);
            for (let i = 0; i < particles.length; i++) {
                let d = p5.Vector.dist(this.position, particles[i].position);
                if (d <= 0) continue;

                let col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if (d < inter_range + col_diff * this.col_sep) {
                    let diff = p5.Vector.sub(this.position, particles[i].position);
                    diff.normalize();
                    diff.div(d);
                    v.add(diff);
                }
            }

            if (v.mag() > 0) {
                v.normalize();
                v.mult(this.maxspeed);
                v.sub(this.velocity);
                v.limit(this.maxforce);
            }

            return v;
        }

        align(particles) {
            const inter_range = 50.0;
            var v = p.createVector(0, 0, 0);
            let count = 0;
            for (let i = 0; i < particles.length; i++) {
                var d = p5.Vector.dist(this.position, particles[i].position);
                var col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if ((d > 0) && (d < inter_range - col_diff * this.col_sep)) {
                    v.add(particles[i].velocity);
                    count++;
                }
            }
            if (count > 0) {
                v.div(count);
                v.normalize();
                v.mult(this.maxspeed);
                v.sub(this.velocity);
                v.limit(this.maxforce);
                return v;
            } else {
                return p.createVector(0, 0, 0);
            }
        }

        cohesion(particles) {
            let neighbor_range = 128.0;
            var v = p.createVector(0, 0, 0);
            var count = 0;
            for (let i = 0; i < particles.length; i++) {
                var d = p5.Vector.dist(this.position, particles[i].position);

                var col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if ((d > 0) && (d < neighbor_range - col_diff * this.col_sep)) {                   
                    v.add(particles[i].position);

                    count++;
                }
            }
            if (count > 0) {
                v.div(count);
                return this.seek(v);
            }
            else {
                return p.createVector(0, 0, 0);
            }
        }

        display(){
            if(this.fin){return;}
            let alpha;
            let dist = p.dist(this.position.x, this.position.y, W/2, H/2);
            let ff = FLAG < 0.33 ? 
            p.noise(this.position.x/10, this.position.y/H*10.) >.4: FLAG < .67 ? p.sin(p.pow(this.position.x/W*10+3,2.1)) + p.cos(this.position.y/H*20+180,3.1)-1 > -.7 :
            p.sin(p.TAU*dist*(this.position.y)*.0001) > -.5;
            if(this.hole_r*.75 < p5.Vector.dist(this.position, this.center) * p.randomGaussian(.2, 1) && ff) {
                G.blendMode(p.ADD);
                alpha = this.alpha + this.fcnt*.06;
            }
            else{
                G.blendMode(p.BLEND);
                alpha = this.alpha + this.fcnt*.01;
            }
            let ratio = 1.0;
            G.strokeWeight(this.radius);
            G.stroke(this.color.x * ratio, this.color.y * ratio, this.color.z * ratio, alpha);
            G.point(
                this.position.x,
                this.position.y
            )

        }
    }


    p.keyPressed = () => {
        if(p.key == 's') {
            G.save("image.png");
        }
    }


};

new p5(sketch);

